// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Request_Qualification_Api {
  def id: Art.BridgeId
  def raw_request_Id : Art.PortId
  def qualified_request_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_request: Factory_Dispatch_Coordinator.Qualified_Request.Type = $

  def put_qualified_request(value : Factory_Dispatch_Coordinator.Qualified_Request.Type) : Unit = {
    Contract(
      Modifies(qualified_request),
      Ensures(
        qualified_request == value
      )
    )
    Spec {
      qualified_request = value
    }

    Art.putValue(qualified_request_Id, Factory_Dispatch_Coordinator.Qualified_Request_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Request_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val raw_request_Id : Art.PortId,
  val qualified_request_Id : Art.PortId) extends Request_Qualification_Api

@datatype class Request_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val raw_request_Id : Art.PortId,
  val qualified_request_Id : Art.PortId) extends Request_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_request: Factory_Dispatch_Coordinator.Dispatch_Request_Sample = $

  def get_raw_request() : Option[Factory_Dispatch_Coordinator.Dispatch_Request_Sample] = {
    Contract(
      Ensures(
        Res == Some(raw_request)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Dispatch_Request_Sample] = Art.getValue(raw_request_Id) match {
      case Some(Factory_Dispatch_Coordinator.Dispatch_Request_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_request.  Expecting 'Factory_Dispatch_Coordinator.Dispatch_Request_Sample_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Dispatch_Request_Sample]()
      case _ => None[Factory_Dispatch_Coordinator.Dispatch_Request_Sample]()
    }
    return value
  }
}
